                  and cb.value -> 'aliases' ? (x.v -> 'aliases' ->> 0))
on conflict do nothing;

-- Nouvelles versions.
with v as (select * from public.game_versions where game_id = 'nd-de-chanceux' and version = (select current_version from public.games where id = 'nd-de-chanceux'))
insert into public.game_versions (game_id, version, rules, config, published_at)
select 'nd-de-chanceux', v.version + 1,
  v.rules || jsonb_build_object(
    'how_to', jsonb_build_array(
      'Le premier joueur est tiré au sort. À ton tour, lance le dé autant de fois que tu veux : chaque résultat de 2 à 6 s''ajoute aux points du tour.',
      'Un 1 fait perdre les points du tour et passe la main ; les points déjà conservés restent acquis.',
      '« Conserver » ajoute les points du tour à ton score et passe la main.',
      'Le premier qui atteint au moins 30 points conservés gagne, au moment où il conserve, sans dernier tour pour l''autre. Le dé est lancé par le serveur.'),
    'details', (select jsonb_agg(case when x #>> '{}' like 'Score : %' then to_jsonb('Score : points conservés sur 30 ; premier à au moins 30 en conservant.'::text) else x end order by o)
                from jsonb_array_elements(v.rules -> 'details') with ordinality e(x, o))),
  jsonb_set(v.config, '{parameters,target}', '30') || jsonb_build_object('version', 'noodeu-m12-2.0.0'),
  now()
from v where coalesce((v.config #>> '{parameters,target}')::int, 100) <> 30;
update public.games set current_version = (select max(version) from public.game_versions where game_id = 'nd-de-chanceux'), updated_at = now() where id = 'nd-de-chanceux';

with v as (select * from public.game_versions where game_id = 'N2-018' and version = (select current_version from public.games where id = 'N2-018'))
insert into public.game_versions (game_id, version, rules, config, published_at)
select 'N2-018', v.version + 1,
  v.rules || jsonb_build_object(
    'objective', 'Une lettre commune, huit rubriques et vos réponses écrites en même temps.',
    'how_to', jsonb_build_array(
      'Une lettre commune est tirée par le serveur ; chacun écrit en même temps un animal, une ville, un métier, un objet, un pays, un prénom, un fruit ou légume et une célébrité qui commencent par cette lettre.',
      'Vous avez 120 secondes (180 si vous le choisissez au salon). « Stop » s''ouvre après 10 secondes, une fois tes huit cases remplies, et arrête la manche pour vous deux.',
      'Les réponses sont révélées ensemble. Une réponse présente dans l''index de sa rubrique est valide ; une réponse inconnue est arbitrée par vous deux en 60 secondes : sans accord, elle reste « non tranchée » et vaut 0.',
      'Par rubrique : même réponse valide, 5 points chacun ; deux réponses valides différentes, 10 chacun ; une seule réponse valide, 15 points. Au plus 120 points par manche et par personne.',
      'Le plus grand total après les manches l''emporte ; égalité possible.'),
    'details', jsonb_build_array(
      'Score : 5 identique, 10 différent, 15 unique valide, 0 vide/invalide/contesté ; maximum théorique 120 par manche et par personne.',
      'Adaptation Noodeu : duo ; 8 rubriques ; 120 s (180 s possibles au salon, réglage à l''essai) ; Stop après 10 s et huit champs remplis.',
      'Adaptation Noodeu : arbitrage consensuel au lieu d''un vote de groupe ; pas de pénalité de contestation.',
      'Rubriques Métier, Prénom, Fruit ou légume et Célébrité : index Noodeu rédigé en octobre 2026, à relire ; il n''est pas exhaustif et tout mot absent peut être arbitré par vous deux.',
      'Accents, majuscules, apostrophes et espaces ignorés ; l''article compte pour l''initiale (Le Caire commence par L) ; pour une célébrité, le nom complet ou le nom d''usage.',
      'Lettres retenues : seulement celles couvertes dans les 8 rubriques ; 3 manches par défaut, 5 ou 7 au salon.',
      'Référence de mécanique : Règles du Petit Bac — petitbac.net (https://petitbac.net/rules.xhtml).',
      'Mots du lot de départ issus de Lexique 4.10 (Boris New, Christophe Pallier et contributeurs de Lexique, https://www.lexique.org/) ; sélection, classement et normalisation : Noodeu. Données dérivées sous licence CC BY-SA 4.0 (https://creativecommons.org/licenses/by-sa/4.0/).',
      'Certaines entrées géographiques proviennent des données structurées de Wikidata (https://www.wikidata.org/), sous CC0 (https://creativecommons.org/publicdomain/zero/1.0/).',
      'Règles rédigées par Noodeu.')),
  v.config || jsonb_build_object(
    'bank', 'petit_bac_huit', 'bank_version', 'pb8-2026-10-28-v1', 'version', 'noodeu-m16-2.0.0',
    'categories', $n$["animal", "ville", "metier", "objet", "pays", "prenom", "fruit-legume", "celebrite"]$n$::jsonb, 'category_labels', $n${"animal": "Animal", "ville": "Ville", "metier": "Métier", "objet": "Objet", "pays": "Pays", "prenom": "Prénom", "fruit-legume": "Fruit ou légume", "celebrite": "Célébrité"}$n$::jsonb,
    'layout', jsonb_build_object('columns', 2, 'rows', 4),
    'settings', jsonb_build_object(
      'cartes', jsonb_build_object('label', 'Nombre de manches', 'default', 3, 'options', jsonb_build_array(3, 5, 7)),
      'timer', jsonb_build_object('label', 'Temps par manche (secondes)', 'default', 120, 'options', jsonb_build_array(120, 180)))),
  now()
from v where v.config ->> 'bank' <> 'petit_bac_huit';
update public.games set current_version = (select max(version) from public.game_versions where game_id = 'N2-018'), updated_at = now() where id = 'N2-018';
